<span class="line"><span style="color:#ABB2BF;">    parent_chunks </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [c </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> c </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> chunks </span><span style="color:#C678DD;">if</span><span style="color:#ABB2BF;"> c.chunk_type </span><span style="color:#56B6C2;">==</span><span style="color:#98C379;"> &quot;parent&quot;</span><span style="color:#ABB2BF;">]</span></span>
